def replace_vowels(text):
 vowels = 'aeiouAEIOU'
 return ''.join('*' if char in vowels else char for char in text)

def validate_bootstrap_size(data, sample):
 if len(sample) != len(data):
 raise ValueError('Bootstrap sample size must equal original dataset size')
 return True

def check_nlp_bag(text, vocabulary):
 counts = []
 text_words = text.lower().split()
 for word in vocabulary:
 counts.append(text_words.count(word))
 return counts

